// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Set;

import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.JoinFactorCostModel;
import org.junit.jupiter.api.Test;

/**
 * Planner deadlines are absolute {@link System#nanoTime()} values. The JDK allows that clock to have any origin, so a
 * real deadline may be zero or negative; only {@link Long#MAX_VALUE} may mean "no deadline".
 */
class OptimizationGoalDeadlineTest {

	@Test
	void negativeAbsoluteDeadlineIsARealDeadline() {
		OptimizationGoal goal = goalWithDeadline(-5L);

		assertEquals(-5L, goal.deadlineNanos(),
				"a nanoTime deadline below zero is legal and must not silently become 'no deadline'");
	}

	@Test
	void zeroAbsoluteDeadlineIsARealDeadline() {
		assertEquals(0L, goalWithDeadline(0L).deadlineNanos());
	}

	@Test
	void onlyLongMaxValueMeansNoDeadline() {
		assertEquals(Long.MAX_VALUE, goalWithDeadline(Long.MAX_VALUE).deadlineNanos());
		assertEquals(Long.MAX_VALUE, OptimizationGoal.root().deadlineNanos());
		assertEquals(Long.MAX_VALUE, OptimizationGoal.root().asBudgeted(null, 10).deadlineNanos());
	}

	@Test
	void budgetedDeadlineAfterANegativeClockReadingIsNotUnbounded() {
		assertEquals(-50L, OptimizationGoal.deadlineAfter(-100L, 50L),
				"a clock reading below zero must still yield a finite deadline");
		assertEquals(Long.MIN_VALUE + 10L, OptimizationGoal.deadlineAfter(Long.MIN_VALUE, 10L));
	}

	@Test
	void budgetedDeadlineSaturatesOnlyOnRealOverflow() {
		assertEquals(15L, OptimizationGoal.deadlineAfter(5L, 10L));
		assertEquals(Long.MAX_VALUE, OptimizationGoal.deadlineAfter(Long.MAX_VALUE - 10L, 100L));
		assertEquals(Long.MAX_VALUE - 1L, OptimizationGoal.deadlineAfter(Long.MAX_VALUE - 10L, 9L));
	}

	private static OptimizationGoal goalWithDeadline(long deadlineNanos) {
		return new OptimizationGoal(PhysicalProperties.ANY, OptimizationGoal.BAG_SEMANTICS,
				OptimizationGoal.CostPolicy.EXACT, CostVector.INFINITE, Set.of(), OptimizationGoal.SearchMode.BUDGETED,
				deadlineNanos, 10, OptimizationGoal.RowGoal.ALL, JoinFactorCostModel.EstimationTier.STANDARD);
	}
}
